UPDATE tools SET long_description = E'Nusii, c''est logiciel de propositions commerciales pour agences. À partir de 29€/mois.\n\nCe qui distingue Nusii : interface épurée et rapide. Ajoutez à ça focus sur l''essentiel (pas de bloat), et notifications en temps réel. Pour les usages intensifs : templates réutilisables. Cas d''usage typique : rédiger des propositions rapidement. On l''utilise aussi pour suivre les propositions envoyées.\n\nÀ garder si : besoin d''un outil simple pour les propositions ou agence ou consultant. À éviter si : besoin de signature intégrée ou fonctionnalités avancées requises. Point de friction : moins de fonctionnalités que Proposify. Bon choix pour les agences qui veulent un outil sans complexité.', long_description_en = E'Nusii is commercial proposal software for agencies. Starting at €29/month.' WHERE slug = 'nusii';
UPDATE tools SET long_description = E'GifGun, c''est export GIF directement depuis After Effects en un clic. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les motion-video et les community-manager.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : export GIF fréquent pour web, réseaux sociaux. À éviter si : pas de besoin GIF — inutile. Achat unique minime — rentable dès le premier GIF livré.', long_description_en = E'GifGun is export GIFs directly from After Effects in one click. Core features are free, with paid plans for advanced use. Most relevant for motion-video and community-manager.\n\nEstimated time saving: 2h/month with regular use.' WHERE slug = 'ae-gifgun';
UPDATE tools SET long_description = E'Kavkom, c''est solution de téléphonie IP pour communications d’entreprise. À partir de 20€/mois. Particulièrement pertinent pour les manager-dsi et les ecommercant.\n\nCe qui distingue Kavkom : spécialisé en voip, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'Kavkom is iP telephony solution for business communications. Starting at €20/month. Most relevant for manager-dsi and ecommercant.\n\nWhat sets Kavkom apart: specialized in voip, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified depending on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'kavkom';
