UPDATE tools SET long_description = E'KeepTruckin, c''est logiciel de gestion de flottes pour entreprises de transport. À partir de 10€/mois. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue KeepTruckin : spécialisé en fleet management, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'KeepTruckin is fleet management software for transport companies. Starting at €10/month. Most relevant for B2B consultants and SaaS founders.\n\nWhat sets KeepTruckin apart: specialized in fleet management, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified based on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'keeptruckin';
UPDATE tools SET long_description = E'PhantomBuster, c''est extraction de données et automatisation LinkedIn. À partir de 56€/mois.\n\nCe qui distingue PhantomBuster : extraction de données LinkedIn puissante. Ajoutez à ça 100+ automations prêtes à l''emploi, et enrichissement de données automatique. Pour les usages intensifs : aPI et webhooks. Cas d''usage typique : scraper des listes de prospects LinkedIn. On l''utilise aussi pour automatiser les demandes de connexion.\n\nÀ garder si : prospection B2B active sur LinkedIn ou besoin d''enrichir des listes de prospects. À éviter si : pas de prospection active ou aversion au risque (ban LinkedIn). Point de friction : prix élevé pour les indépendants. Rentable si vous générez 5+ leads qualifiés par mois grâce à l''outil.', long_description_en = E'PhantomBuster is data extraction and LinkedIn automation. Starting at €56/month.' WHERE slug = 'phantombuster';
UPDATE tools SET long_description = E'Figma Tokens (Tokens Studio), c''est gestion des design tokens dans Figma avec sync Git. Indispensable pour les design systems. À partir de 7.79€/mois. Particulièrement pertinent pour les ux-ui et les developpeur-solo.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : design system avec sync code — indispensable. À éviter si : pas de design system — inutile. Rentable dès le premier design system en production.', long_description_en = E'Figma Tokens (Tokens Studio) is design token management in Figma with Git sync. Essential for design systems. Starting at €7.79/month. Most relevant for ux-ui and solo developers.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'figma-tokens';
