UPDATE tools SET long_description = E'Waalaxy, c''est prospection LinkedIn automatisée. À partir de 40€/mois.\n\nCe qui distingue Waalaxy : interface intuitive (pas besoin d''être technique). Ajoutez à ça cRM de prospection intégré, et séquences LinkedIn + Email. Pour les usages intensifs : communauté française active. Cas d''usage typique : automatiser les demandes de connexion LinkedIn. On l''utilise aussi pour envoyer des séquences de messages personnalisés.\n\nÀ garder si : prospection LinkedIn active ou besoin d''un outil simple sans courbe d''apprentissage. À éviter si : pas de prospection LinkedIn ou besoin d''outreach email avancé. Point de friction : limité à LinkedIn principalement. Utile dès 20+ connexions LinkedIn par semaine.', long_description_en = E'Waalaxy is automated LinkedIn prospecting. Starting at €40/month.' WHERE slug = 'waalaxy';
UPDATE tools SET long_description = E'RubberHose 2, c''est animation de membres et tentacules organiques sans rigging complexe dans AE. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les motion-video.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : animation de personnages simples avec membres organiques. À éviter si : duik déjà maîtrisé — doublon rigging. Pertinent si Duik est trop complexe pour vos besoins. Si le budget le permet, ae-duik est souvent une meilleure option.', long_description_en = E'RubberHose 2 is organic limb and tentacle animation without complex rigging in AE. Core features are free, with paid plans for advanced use. Most relevant for motion-video.\n\nEstimated time saving: 3h/month with regular use.\n\nIf budget allows, ae-duik is often a better fit.' WHERE slug = 'ae-rubberhose';
