UPDATE tools SET long_description = E'Lendio, c''est service de prêts professionnels avec multiples options de financement. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les consultants B2B et les daf-finance.\n\nCe qui distingue Lendio : spécialisé en business loans, et interface professionnelle. Gain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'Lendio is business loan service with multiple financing options. Core features are free, with paid plans for advanced use. Most relevant for B2B consultants and daf-finance.\n\nWhat sets Lendio apart: specialized in business loans, and professional interface. Estimated time saving: 2h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. Free, keep it if it''s useful.' WHERE slug = 'lendio';
UPDATE tools SET long_description = E'Arc Browser, c''est navigateur repensé pour la productivité. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Arc Browser : organisation automatique des onglets par espace. Ajoutez à ça interface minimaliste et esthétique, et mini-apps (Easels, Notes, Boosts). Pour les usages intensifs : archivage automatique des vieux onglets. Cas d''usage typique : séparer les onglets par projet/client. On l''utilise aussi pour réduire le chaos des 50+ onglets.\n\nÀ garder si : 50+ onglets ouverts régulièrement ou multi-projets (besoin d''espaces séparés). À éviter si : satisfait de Chrome/Firefox ou peu d''onglets. Point de friction : basé sur Chromium (mêmes limites). Gratuit — à essayer pendant 1 semaine pour voir si l''organisation d''onglets vous convient.', long_description_en = E'Arc Browser is redesigned browser for productivity. Core features are free, with paid plans for advanced use.' WHERE slug = 'arc-browser';
UPDATE tools SET long_description = E'Mailgun, c''est service d’envoi d’emails pour développeurs. À partir de 10€/mois. Particulièrement pertinent pour les developpeur-solo et les fondateurs SaaS.\n\nCe qui distingue Mailgun : spécialisé en email delivery, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'Mailgun is email sending service for developers. Starting at €10/month. Most relevant for solo developers and SaaS founders.\n\nWhat sets Mailgun apart: specialized in email delivery, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to check based on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'mailgun';
UPDATE tools SET long_description = E'Notionlytics, c''est analytics pour pages Notion partagées. À partir de 5€/mois.\n\nCe qui distingue Notionlytics : analytics simples pour pages Notion. Ajoutez à ça pas de configuration technique, et vues, temps passé, sources. Pour les usages intensifs : intégration Notion native. Cas d''usage typique : suivre les vues sur un portfolio Notion. On l''utilise aussi pour mesurer l''engagement sur une documentation client.\n\nÀ garder si : notion utilisé comme site public ou portfolio ou besoin de savoir qui consulte vos docs. À éviter si : notion en usage privé uniquement ou site web classique (utiliser Plausible). Point de friction : limité aux pages Notion publiques. Utile si vous partagez régulièrement des pages Notion avec des clients ou prospects.', long_description_en = E'Notionlytics is analytics for shared Notion pages. Starting at €5/month.' WHERE slug = 'notionlytics';
